PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,region TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('khuddam','atfal')),guardian_name TEXT,guardian_phone TEXT,guardian_consent INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,participant_id TEXT NOT NULL REFERENCES participants(id),reference_code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,rationale TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',file_key TEXT NOT NULL,file_name TEXT NOT NULL,file_type TEXT NOT NULL,file_size INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('super_admin','competition_admin','secretary','judge','read_only')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS judge_assignments(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL REFERENCES submissions(id),judge_id TEXT NOT NULL REFERENCES admin_users(id),assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(submission_id,judge_id));
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,submission_id TEXT NOT NULL REFERENCES submissions(id),judge_id TEXT NOT NULL REFERENCES admin_users(id),originality REAL NOT NULL,relevance REAL NOT NULL,symbolism REAL NOT NULL,visual_quality REAL NOT NULL,versatility REAL NOT NULL,comments TEXT,total_score REAL NOT NULL,submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(submission_id,judge_id));
CREATE TABLE IF NOT EXISTS competition_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
